/**
 * Illustrated avatar asset catalog (MAKE-291).
 *
 * Approved Fox, Bear, Owl, Dragon, and Android variants are embedded as optimized WebP data
 * URIs at 32px, 48px, and 96px. Self-contained sources render in Next.js and
 * Electron file:// contexts; platform copies remain available for static web
 * serving and Expo bundling. Original 512px PNG/WebP masters are retained
 * alongside the optimized tiers.
 */

export type IllustratedAvatarArchetype = "fox" | "bear" | "owl" | "dragon" | "android";
export type IllustratedAvatarVariant = "general" | "developer" | "auditor";
export type FoxVariant = IllustratedAvatarVariant;
export type BearVariant = IllustratedAvatarVariant;
export type OwlVariant = IllustratedAvatarVariant;
export type DragonVariant = IllustratedAvatarVariant;
export type AndroidVariant = IllustratedAvatarVariant;
export type AvatarSizeTier = 32 | 48 | 96;

export const ILLUSTRATED_VARIANTS: readonly IllustratedAvatarVariant[] = [
  "general",
  "developer",
  "auditor",
] as const;
export const FOX_VARIANTS = ILLUSTRATED_VARIANTS;
export const BEAR_VARIANTS = ILLUSTRATED_VARIANTS;
export const OWL_VARIANTS = ILLUSTRATED_VARIANTS;
export const DRAGON_VARIANTS = ILLUSTRATED_VARIANTS;
export const ANDROID_VARIANTS = ILLUSTRATED_VARIANTS;

export interface IllustratedAvatarAsset {
  archetype: IllustratedAvatarArchetype;
  variant: IllustratedAvatarVariant;
  src: string;
  srcSet: string;
  width: number;
  height: number;
  alt: string;
}
export type FoxAvatarAsset = IllustratedAvatarAsset;
export type BearAvatarAsset = IllustratedAvatarAsset;
export type OwlAvatarAsset = IllustratedAvatarAsset;
export type DragonAvatarAsset = IllustratedAvatarAsset;
export type AndroidAvatarAsset = IllustratedAvatarAsset;

