const DATA_URIS: Record<IllustratedAvatarArchetype, Record<IllustratedAvatarVariant, Record<AvatarSizeTier, string>>> = {
  fox: FOX_DATA_URIS,
  bear: BEAR_DATA_URIS,
  owl: OWL_DATA_URIS,
  dragon: DRAGON_DATA_URIS,
  android: ANDROID_DATA_URIS,
};

const TIERS: readonly AvatarSizeTier[] = [32, 48, 96];

/**
 * True only when the catalog holds a complete, non-empty asset set (every
 * optimized tier) for the archetype + variant. Renderers use this to fall back
 * to the generic procedural avatar for unsupported archetypes or missing
 * assets instead of rendering a broken image.
 */
export function hasIllustratedAvatarAsset(
  archetype: string,
  variant: string,
): boolean {
  const byVariant = (
    DATA_URIS as Record<
      string,
      Record<string, Record<number, string> | undefined> | undefined
    >
  )[archetype];
  const uris = byVariant?.[variant];
  return (
    !!uris &&
    TIERS.every((tier) => typeof uris[tier] === "string" && uris[tier].length > 0)
  );
}

function primaryTierFor(targetSizePx: number): AvatarSizeTier {
  if (targetSizePx > 48) return 96;
  if (targetSizePx > 24) return 48;
  return 32;
}

export function getIllustratedAvatarAsset(
  archetype: IllustratedAvatarArchetype,
  variant: IllustratedAvatarVariant = "general",
  targetSizePx: number = 32,
): IllustratedAvatarAsset {
  const v = ILLUSTRATED_VARIANTS.includes(variant) ? variant : "general";
  const uris = DATA_URIS[archetype][v];
  const title = `${archetype[0]?.toUpperCase()}${archetype.slice(1)} ${v[0]?.toUpperCase()}${v.slice(1)}`;
  return {
    archetype,
    variant: v,
    src: uris[primaryTierFor(targetSizePx)],
    srcSet: `${uris[32]} 32w, ${uris[48]} 48w, ${uris[96]} 96w`,
    width: targetSizePx,
    height: targetSizePx,
    alt: title,
  };
}

export function getFoxAvatarAsset(variant: FoxVariant = "general", targetSizePx: number = 32): FoxAvatarAsset {
  return getIllustratedAvatarAsset("fox", variant, targetSizePx);
}
export function getBearAvatarAsset(variant: BearVariant = "general", targetSizePx: number = 32): BearAvatarAsset {
  return getIllustratedAvatarAsset("bear", variant, targetSizePx);
}
export function getOwlAvatarAsset(variant: OwlVariant = "general", targetSizePx: number = 32): OwlAvatarAsset {
  return getIllustratedAvatarAsset("owl", variant, targetSizePx);
}
export function getDragonAvatarAsset(variant: DragonVariant = "general", targetSizePx: number = 32): DragonAvatarAsset {
  return getIllustratedAvatarAsset("dragon", variant, targetSizePx);
}
export function getAndroidAvatarAsset(variant: AndroidVariant = "general", targetSizePx: number = 32): AndroidAvatarAsset {
  return getIllustratedAvatarAsset("android", variant, targetSizePx);
}
